SELECT DISTINCT JSON_OBJECT('table','merchant_sources','row',JSON_OBJECT(
'zone',z.short_name,'npc_id',n.id,'npc_name',n.name,'npc_class',n.class,
'alt_currency_id',n.alt_currency_id,'npc_faction_id',n.npc_faction_id,
'primary_faction',f.primaryfaction,
'merchant', JSON_OBJECT('merchantid',m.`merchantid`,'slot',m.`slot`,'item',m.`item`,'faction_required',m.`faction_required`,'level_required',m.`level_required`,'min_status',m.`min_status`,'max_status',m.`max_status`,'alt_currency_cost',m.`alt_currency_cost`,'classes_required',m.`classes_required`,'probability',m.`probability`,'bucket_name',m.`bucket_name`,'bucket_value',m.`bucket_value`,'bucket_comparison',m.`bucket_comparison`,'min_expansion',m.`min_expansion`,'max_expansion',m.`max_expansion`,'content_flags',m.`content_flags`,'content_flags_disabled',m.`content_flags_disabled`)))
FROM zone z JOIN spawn2 s ON s.zone=z.short_name AND s.version=z.version
JOIN spawnentry se ON se.spawngroupID=s.spawngroupID JOIN npc_types n ON n.id=se.npcID
JOIN merchantlist m ON m.merchantid=n.merchant_id
LEFT JOIN npc_faction f ON f.id=n.npc_faction_id
WHERE z.version=0 AND (z.expansion=0 OR z.short_name='poknowledge') AND s._condition=0 AND se.chance>0
AND NOT EXISTS(SELECT 1 FROM spawn2_disabled sd WHERE sd.spawn2_id=s.id AND sd.instance_id=0 AND sd.disabled<>0)
AND (s.min_expansion=-1 OR s.min_expansion=0) AND (s.max_expansion=-1 OR s.max_expansion>=0) AND COALESCE(s.content_flags,'')='' AND COALESCE(s.content_flags_disabled,'')='' AND (se.min_expansion=-1 OR se.min_expansion=0) AND (se.max_expansion=-1 OR se.max_expansion>=0) AND COALESCE(se.content_flags,'')='' AND COALESCE(se.content_flags_disabled,'')='' AND (m.min_expansion=-1 OR m.min_expansion=0) AND (m.max_expansion=-1 OR m.max_expansion>=0) AND COALESCE(m.content_flags,'')='' AND COALESCE(m.content_flags_disabled,'')=''
AND m.min_status<=0 AND m.max_status>=0 AND m.level_required<=50 AND m.probability>0;
SELECT JSON_OBJECT('table','global_loot','row',JSON_OBJECT('id',g.`id`,'description',g.`description`,'loottable_id',g.`loottable_id`,'enabled',g.`enabled`,'min_level',g.`min_level`,'max_level',g.`max_level`,'rare',g.`rare`,'raid',g.`raid`,'race',g.`race`,'class',g.`class`,'bodytype',g.`bodytype`,'zone',g.`zone`,'hot_zone',g.`hot_zone`,'min_expansion',g.`min_expansion`,'max_expansion',g.`max_expansion`,'content_flags',g.`content_flags`,'content_flags_disabled',g.`content_flags_disabled`)) FROM global_loot g;
SELECT JSON_OBJECT('table','global_loot_entries','row',JSON_OBJECT(
        'global_id',g.id,'lootdrop_id',d.id,'item_id',e.item_id,'chance',e.chance,
        'multiplier',e.multiplier,'npc_min_level',e.npc_min_level,'npc_max_level',e.npc_max_level))
        FROM global_loot g JOIN loottable l ON l.id=g.loottable_id
        JOIN loottable_entries t ON t.loottable_id=l.id JOIN lootdrop d ON d.id=t.lootdrop_id
        JOIN lootdrop_entries e ON e.lootdrop_id=d.id
        WHERE g.enabled=1 AND t.probability>0 AND t.multiplier>0 AND e.chance>0 AND e.multiplier>0
        AND (g.min_expansion=-1 OR g.min_expansion=0) AND (g.max_expansion=-1 OR g.max_expansion>=0) AND COALESCE(g.content_flags,'')='' AND COALESCE(g.content_flags_disabled,'')='' AND (l.min_expansion=-1 OR l.min_expansion=0) AND (l.max_expansion=-1 OR l.max_expansion>=0) AND COALESCE(l.content_flags,'')='' AND COALESCE(l.content_flags_disabled,'')='' AND (d.min_expansion=-1 OR d.min_expansion=0) AND (d.max_expansion=-1 OR d.max_expansion>=0) AND COALESCE(d.content_flags,'')='' AND COALESCE(d.content_flags_disabled,'')='' AND (e.min_expansion=-1 OR e.min_expansion=0) AND (e.max_expansion=-1 OR e.max_expansion>=0) AND COALESCE(e.content_flags,'')='' AND COALESCE(e.content_flags_disabled,'')='';
SELECT JSON_OBJECT('table','recipes','row',JSON_OBJECT('id',r.`id`,'name',r.`name`,'tradeskill',r.`tradeskill`,'skillneeded',r.`skillneeded`,'trivial',r.`trivial`,'nofail',r.`nofail`,'replace_container',r.`replace_container`,'notes',r.`notes`,'must_learn',r.`must_learn`,'learned_by_item_id',r.`learned_by_item_id`,'quest',r.`quest`,'enabled',r.`enabled`,'min_expansion',r.`min_expansion`,'max_expansion',r.`max_expansion`,'content_flags',r.`content_flags`,'content_flags_disabled',r.`content_flags_disabled`)) FROM tradeskill_recipe r WHERE r.id IN (SELECT DISTINCT e.recipe_id FROM tradeskill_recipe_entries e
JOIN items i ON i.id=e.item_id JOIN tradeskill_recipe r ON r.id=e.recipe_id
WHERE e.successcount>0 AND r.enabled=1 AND (r.min_expansion=-1 OR r.min_expansion=0) AND (r.max_expansion=-1 OR r.max_expansion>=0) AND COALESCE(r.content_flags,'')='' AND COALESCE(r.content_flags_disabled,'')='' AND i.reqlevel<=50 AND (i.slots & 2097150)>0 AND (i.classes & 7747)>0 AND (i.races & 1)>0 AND (i.deity=0 OR (i.deity & 1)>0));
SELECT JSON_OBJECT('table','recipe_entries','row',JSON_OBJECT('id',e.`id`,'recipe_id',e.`recipe_id`,'item_id',e.`item_id`,'successcount',e.`successcount`,'failcount',e.`failcount`,'componentcount',e.`componentcount`,'salvagecount',e.`salvagecount`,'iscontainer',e.`iscontainer`)) FROM tradeskill_recipe_entries e WHERE e.recipe_id IN (SELECT DISTINCT e.recipe_id FROM tradeskill_recipe_entries e
JOIN items i ON i.id=e.item_id JOIN tradeskill_recipe r ON r.id=e.recipe_id
WHERE e.successcount>0 AND r.enabled=1 AND (r.min_expansion=-1 OR r.min_expansion=0) AND (r.max_expansion=-1 OR r.max_expansion>=0) AND COALESCE(r.content_flags,'')='' AND COALESCE(r.content_flags_disabled,'')='' AND i.reqlevel<=50 AND (i.slots & 2097150)>0 AND (i.classes & 7747)>0 AND (i.races & 1)>0 AND (i.deity=0 OR (i.deity & 1)>0));
